// Drop-in Remotion composition driven by narration.json (generated by scripts/narrate.py).
import {AbsoluteFill, Audio, Sequence, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';
import narration from '../public/narration/narration.json';

type Caption = {text: string; startMs: number; endMs: number};

const Subtitle: React.FC<{captions: Caption[]}> = ({captions}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const ms = (frame / fps) * 1000;
  // show the current sentence-sized window of words, highlight the spoken one
  const i = captions.findIndex((c) => ms >= c.startMs && ms < c.endMs);
  if (i < 0) return null;
  const from = Math.max(0, i - 3);
  return (
    <div style={{position: 'absolute', bottom: 80, width: '100%', textAlign: 'center', fontSize: 56, color: 'white'}}>
      {captions.slice(from, i + 4).map((c, k) => (
        <span key={k} style={{opacity: from + k === i ? 1 : 0.55}}>{c.text}</span>
      ))}
    </div>
  );
};

export const Narrated: React.FC = () => (
  <AbsoluteFill style={{backgroundColor: '#111827'}}>
    {narration.scenes.map((s) => (
      <Sequence key={s.id} from={s.startFrame} durationInFrames={s.durationInFrames}>
        <Audio src={staticFile(`narration/${s.file}`)} />
        <Subtitle captions={s.captions as Caption[]} />
      </Sequence>
    ))}
  </AbsoluteFill>
);

